import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { apiRequest, clearSession, toDashboardReservation } from "../api";

const GUESTS = [
  { name: "Tito Badang",  init: "TB", email: "tito@email.com",  phone: "+63 917-111-2222", visits: 5, lastVisit: "May 10", status: "Checked In", notes: "Prefers ground floor" },
  { name: "Bonji Manoto", init: "BM", email: "bonji@email.com", phone: "+63 918-222-3333", visits: 2, lastVisit: "May 11", status: "Upcoming",   notes: "Birthday celebration" },
  { name: "Gelo Cruz",    init: "GC", email: "gelo@email.com",  phone: "+63 916-333-4444", visits: 1, lastVisit: "May 12", status: "Upcoming",   notes: "Corporate event" },
];

const ROOMS = [
  { name: "Regular Room A", type: "Regular Room", icon: "bi-door-closed",     capacity: 2,   price: "₱350 / 3 hrs",     status: "Available",   amenities: ["AC", "WiFi", "TV"] },
  { name: "Regular Room B", type: "Regular Room", icon: "bi-door-closed",     capacity: 2,   price: "₱350 / 3 hrs",     status: "Occupied",    amenities: ["AC", "WiFi", "TV"] },
  { name: "Luxury Room A",  type: "Luxury Room",  icon: "bi-gem",             capacity: 4,   price: "₱1,200 / night",   status: "Occupied",    amenities: ["AC", "WiFi", "TV", "Mini Bar", "Jacuzzi"] },
  { name: "Luxury Room B",  type: "Luxury Room",  icon: "bi-gem",             capacity: 4,   price: "₱1,200 / night",   status: "Available",   amenities: ["AC", "WiFi", "TV", "Mini Bar", "Jacuzzi"] },
  { name: "Private Pool",   type: "Experience",   icon: "bi-water",           capacity: 8,   price: "₱350 / session",   status: "Available",   amenities: ["Private Pool", "Shower", "Towels"] },
  { name: "Entire Villa",   type: "Full Package", icon: "bi-house-heart",     capacity: 20,  price: "By arrangement",   status: "Available",   amenities: ["All Rooms", "Pool", "Event Space", "Full Staff"] },
];

const CONVERSATIONS = [
  {
    id: 2, name: "Bonji Manoto", init: "BM", role: "Guest",
    last: "Is the event space available on May 11?", time: "9:47 AM", unread: 2,
    messages: [
      { from: "them", text: "Hi, I'm planning a birthday party for 50 people.", time: "9:40 AM" },
      { from: "them", text: "Is the event space available on May 11?", time: "9:47 AM" },
    ],
  },
  {
    id: 3, name: "Gelo Cruz", init: "GC", role: "Guest",
    last: "We need a projector for the corporate event.", time: "Yesterday", unread: 1,
    messages: [
      { from: "them", text: "We need a projector for the corporate event.", time: "Yesterday" },
    ],
  },
  {
    id: 4, name: "Admin User", init: "AD", role: "Admin",
    last: "Please update the room availability report.", time: "Yesterday", unread: 0,
    messages: [
      { from: "them", text: "Please update the room availability report.", time: "Yesterday" },
      { from: "me",   text: "Sure, I'll have it done by end of day.", time: "Yesterday" },
    ],
  },
];

const navItems = [
  { key: "dashboard", label: "Dashboard", icon: "bi-grid-1x2"        },
  { key: "bookings",  label: "Bookings",  icon: "bi-calendar-check"  },
  { key: "guests",    label: "Guests",    icon: "bi-people"           },
  { key: "rooms",     label: "Rooms and Services",     icon: "bi-house-door"       },
  { key: "messages",  label: "Messages",  icon: "bi-chat-dots"        },
];

function StatusBadge({ status }) {
  const map = {
    Confirmed:    { bg: "#DCFCE7", color: "#166534" },
    "Checked In": { bg: "#DBEAFE", color: "#1D4ED8" },
    "Checked Out":{ bg: "#F3F4F6", color: "#6B7280" },
    Pending:      { bg: "#FFEDD5", color: "#C2410C" },
    Cancelled:    { bg: "#FEE2E2", color: "#991B1B" },
    Available:    { bg: "#DCFCE7", color: "#166534" },
    Occupied:     { bg: "#DBEAFE", color: "#1D4ED8" },
    Maintenance:  { bg: "#FFEDD5", color: "#C2410C" },
    Upcoming:     { bg: "#FFF7ED", color: "#F97316" },
  };
  const s = map[status] || { bg: "#FFF7ED", color: "#F97316" };
  return (
    <span style={{ background: s.bg, color: s.color, padding: "5px 12px", borderRadius: 999, fontSize: 12, fontWeight: 700 }}>
      {status}
    </span>
  );
}

function Avatar({ init, size = 38, bg = "#F97316", color = "#fff" }) {
  return (
    <div style={{ width: size, height: size, borderRadius: "50%", background: bg, color, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, fontSize: size * 0.35, flexShrink: 0 }}>
      {init}
    </div>
  );
}

function DashboardPanel({ bookings }) {
  return (
    <>
      <div style={S.statsGrid}>
        {[
          { label: "TODAY BOOKINGS",  value: "24",      text: "+12% from yesterday",   icon: "bi-calendar-check" },
          { label: "AVAILABLE ROOMS", value: "12",      text: "Ready for reservation", icon: "bi-house-door"     },
          { label: "CHECK INS",       value: "8",       text: "Guests arriving today", icon: "bi-box-arrow-in-right" },
        ].map(c => (
          <div key={c.label} style={S.card}>
            <div style={{ width: 40, height: 40, borderRadius: 12, background: "#FFF7ED", border: "1px solid #FED7AA", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 14 }}>
              <i className={`bi ${c.icon}`} style={{ fontSize: 18, color: "#F97316" }} />
            </div>
            <h3 style={S.cardLabel}>{c.label}</h3>
            <h2 style={S.cardValue}>{c.value}</h2>
            <p style={S.cardText}>{c.text}</p>
          </div>
        ))}
      </div>
      <div style={S.tableCard}>
        <div style={S.tableHeader}>
          <h2 style={S.tableTitle}>Recent Reservations</h2>
          <button style={S.orangeBtn}>View All</button>
        </div>
        <table style={S.table}>
          <thead>
            <tr>{["Guest","Room","Check In","Status"].map(h => <th key={h} style={S.th}>{h}</th>)}</tr>
          </thead>
          <tbody>
            {bookings.slice(0, 5).map((b, i) => (
              <tr key={b.id}>
                <td style={{ ...S.td, borderBottom: i === 4 ? "none" : S.td.borderBottom }}>{b.customer}</td>
                <td style={{ ...S.td, borderBottom: i === 4 ? "none" : S.td.borderBottom }}>{b.room}</td>
                <td style={{ ...S.td, borderBottom: i === 4 ? "none" : S.td.borderBottom }}>{b.checkin}</td>
                <td style={{ ...S.td, borderBottom: i === 4 ? "none" : S.td.borderBottom }}><StatusBadge status={b.status} /></td>
              </tr>
            ))}
            {bookings.length === 0 && <tr><td colSpan={4} style={S.td}>No reservations yet.</td></tr>}
          </tbody>
        </table>
      </div>
    </>
  );
}

function BookingsPanel({ bookings, onStatusChange }) {
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("All");

  const filtered = bookings.filter(b => {
    const matchSearch = b.customer.toLowerCase().includes(search.toLowerCase()) || b.room.toLowerCase().includes(search.toLowerCase()) || b.id.toLowerCase().includes(search.toLowerCase());
    const matchFilter = filter === "All" || b.status === filter;
    return matchSearch && matchFilter;
  });

  const stats = [
    { label: "TOTAL BOOKINGS", value: bookings.length,                                        icon: "bi-journal-text"    },
    { label: "CONFIRMED",      value: bookings.filter(b => b.status === "Confirmed").length,   icon: "bi-check-circle"    },
    { label: "PENDING",        value: bookings.filter(b => b.status === "Pending").length,     icon: "bi-hourglass-split" },
    { label: "CHECKED IN",     value: bookings.filter(b => b.status === "Checked In").length,  icon: "bi-door-open"       },
  ];

  return (
    <>
      <div style={S.statsGrid}>
        {stats.map(s => (
          <div key={s.label} style={S.card}>
            <div style={{ width: 40, height: 40, borderRadius: 12, background: "#FFF7ED", border: "1px solid #FED7AA", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 14 }}>
              <i className={`bi ${s.icon}`} style={{ fontSize: 18, color: "#F97316" }} />
            </div>
            <h3 style={S.cardLabel}>{s.label}</h3>
            <h2 style={{ ...S.cardValue, fontSize: 36 }}>{s.value}</h2>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: 12, marginBottom: 20, alignItems: "center" }}>
        <div style={{ flex: 1, position: "relative" }}>
          <i className="bi bi-search" style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)", color: "#9CA3AF", fontSize: 15 }} />
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by guest, room, or booking ID..." style={{ ...S.searchInput, paddingLeft: 40 }} />
        </div>
        {["All","Confirmed","Pending","Checked In","Cancelled"].map(f => (
          <button key={f} onClick={() => setFilter(f)} style={{ padding: "10px 16px", borderRadius: 12, border: "1px solid", borderColor: filter === f ? "#F97316" : "#FED7AA", background: filter === f ? "#F97316" : "#fff", color: filter === f ? "#fff" : "#6B7280", fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: "Inter, sans-serif" }}>
            {f}
          </button>
        ))}
      </div>

      <div style={S.tableCard}>
        <div style={S.tableHeader}>
          <h2 style={S.tableTitle}>All Bookings</h2>
          <button style={S.orangeBtn}>
            <i className="bi bi-plus-lg" style={{ marginRight: 6 }} />
            New Booking
          </button>
        </div>
        <table style={S.table}>
          <thead>
            <tr>{["Booking ID","Guest","Room","Check In","Check Out","Pax","Amount","Status",""].map(h => <th key={h} style={S.th}>{h}</th>)}</tr>
          </thead>
          <tbody>
            {filtered.map((b, i) => (
              <tr key={b.id}>
                <td style={{ ...S.td, color: "#9CA3AF", fontSize: 12, borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>{b.id}</td>
                <td style={{ ...S.td, fontWeight: 600, borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>{b.customer}</td>
                <td style={{ ...S.td, borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>{b.room}</td>
                <td style={{ ...S.td, color: "#6B7280", borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>{b.checkin}</td>
                <td style={{ ...S.td, color: "#6B7280", borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>{b.checkout}</td>
                <td style={{ ...S.td, textAlign: "center", borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>{b.pax}</td>
                <td style={{ ...S.td, fontWeight: 700, color: "#F97316", borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>{b.amount}</td>
                <td style={{ ...S.td, borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}><StatusBadge status={b.status} /></td>
                <td style={{ ...S.td, borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>
                  <select aria-label={`Update ${b.id} status`} style={S.searchInput} value={b.status} onChange={(event) => onStatusChange(b, event.target.value)}>
                    {["Pending", "Confirmed", "Cancelled", "Checked In", "Completed"].map((status) => <option key={status}>{status}</option>)}
                  </select>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr><td colSpan={9} style={{ ...S.td, textAlign: "center", color: "#9CA3AF", padding: 32, borderBottom: "none" }}>No bookings found.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </>
  );
}

function GuestsPanel() {
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState(null);

  const filtered = GUESTS.filter(g =>
    g.name.toLowerCase().includes(search.toLowerCase()) ||
    g.email.toLowerCase().includes(search.toLowerCase())
  );

  const guest = selected !== null ? GUESTS[selected] : null;

  return (
    <div style={{ display: "grid", gridTemplateColumns: guest ? "1fr 340px" : "1fr", gap: 20 }}>
      <div>
        <div style={{ display: "flex", gap: 12, marginBottom: 20, alignItems: "center" }}>
          <div style={{ flex: 1, position: "relative" }}>
            <i className="bi bi-search" style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)", color: "#9CA3AF", fontSize: 15 }} />
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search guests..." style={{ ...S.searchInput, paddingLeft: 40 }} />
          </div>
          <button style={S.orangeBtn}>
            <i className="bi bi-person-plus" style={{ marginRight: 6 }} />
            Add Guest
          </button>
        </div>

        <div style={S.tableCard}>
          <div style={S.tableHeader}>
            <h2 style={S.tableTitle}>Guest Directory</h2>
            <span style={{ fontSize: 13, color: "#9CA3AF" }}>{filtered.length} guests</span>
          </div>
          <table style={S.table}>
            <thead>
              <tr>{["Guest","Contact","Pax","Last Visit","Status",""].map(h => <th key={h} style={S.th}>{h}</th>)}</tr>
            </thead>
            <tbody>
              {filtered.map((g, i) => (
                <tr key={g.name} onClick={() => setSelected(GUESTS.indexOf(g))} style={{ cursor: "pointer", background: selected === GUESTS.indexOf(g) ? "#FFF7ED" : "transparent" }}>
                  <td style={{ ...S.td, borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                      <Avatar init={g.init} size={36} />
                      <div>
                        <div style={{ fontWeight: 600, fontSize: 14 }}>{g.name}</div>
                        <div style={{ fontSize: 12, color: "#9CA3AF" }}>{g.email}</div>
                      </div>
                    </div>
                  </td>
                  <td style={{ ...S.td, color: "#6B7280", fontSize: 13, borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>{g.phone}</td>
                  <td style={{ ...S.td, textAlign: "center", fontWeight: 700, borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>{g.visits}</td>
                  <td style={{ ...S.td, color: "#6B7280", borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>{g.lastVisit}</td>
                  <td style={{ ...S.td, borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}><StatusBadge status={g.status} /></td>
                  <td style={{ ...S.td, borderBottom: i === filtered.length-1 ? "none" : S.td.borderBottom }}>
                    <i className="bi bi-chevron-right" style={{ color: "#9CA3AF", fontSize: 16 }} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {guest && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ ...S.tableCard, padding: 24 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 20 }}>
              <h2 style={{ ...S.tableTitle, fontSize: 16 }}>Guest Profile</h2>
              <button onClick={() => setSelected(null)} style={{ background: "none", border: "none", color: "#9CA3AF", cursor: "pointer", lineHeight: 1 }}>
                <i className="bi bi-x-lg" style={{ fontSize: 18 }} />
              </button>
            </div>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 10, marginBottom: 20, padding: 16, background: "#FFF7ED", borderRadius: 16, border: "1px solid #FED7AA" }}>
              <Avatar init={guest.init} size={60} />
              <div style={{ textAlign: "center" }}>
                <div style={{ fontWeight: 800, fontSize: 17, color: "#111827" }}>{guest.name}</div>
                <div style={{ fontSize: 13, color: "#9CA3AF", marginBottom: 8 }}>{guest.role || "Guest"}</div>
                <StatusBadge status={guest.status} />
              </div>
            </div>
            {[["Email", guest.email],["Phone", guest.phone],["Pax", guest.visits],["Last Visit", guest.lastVisit]].map(([l,v]) => (
              <div key={l} style={{ display: "flex", justifyContent: "space-between", padding: "10px 0", borderBottom: "1px solid #F9FAFB" }}>
                <span style={{ fontSize: 13, color: "#9CA3AF", fontWeight: 600 }}>{l}</span>
                <span style={{ fontSize: 13, color: "#111827", fontWeight: 600 }}>{v}</span>
              </div>
            ))}
            {guest.notes && (
              <div style={{ marginTop: 14, padding: "12px 14px", background: "#FFF7ED", border: "1px solid #FED7AA", borderRadius: 12, fontSize: 13, color: "#6B7280", display: "flex", gap: 8 }}>
                <i className="bi bi-sticky" style={{ color: "#F97316", fontSize: 15, flexShrink: 0, marginTop: 1 }} />
                {guest.notes}
              </div>
            )}
            <button style={{ ...S.orangeBtn, width: "100%", marginTop: 16, borderRadius: 14, padding: "12px" }}>
              <i className="bi bi-clock-history" style={{ marginRight: 8 }} />
              View Full History
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function RoomsPanel() {
  const [filter, setFilter] = useState("All");
  const filtered = ROOMS.filter(r => filter === "All" || r.status === filter);

  const statusColor = {
    Available:   { bg: "#DCFCE7", color: "#166534", dot: "#16A34A" },
    Occupied:    { bg: "#DBEAFE", color: "#1D4ED8", dot: "#2563EB" },
    Maintenance: { bg: "#FFEDD5", color: "#C2410C", dot: "#EA580C" },
  };

  const summaryStats = [
    { label: "TOTAL ROOMS",  value: ROOMS.length,                                        icon: "bi-building",           color: "#111827" },
    { label: "AVAILABLE",    value: ROOMS.filter(r => r.status === "Available").length,   icon: "bi-check-circle",       color: "#16A34A" },
    { label: "OCCUPIED",     value: ROOMS.filter(r => r.status === "Occupied").length,    icon: "bi-person-fill",        color: "#2563EB" },
    { label: "MAINTENANCE",  value: ROOMS.filter(r => r.status === "Maintenance").length, icon: "bi-tools",              color: "#EA580C" },
  ];

  return (
    <>
      <div style={S.statsGrid}>
        {summaryStats.map(s => (
          <div key={s.label} style={S.card}>
            <div style={{ width: 40, height: 40, borderRadius: 12, background: "#FFF7ED", border: "1px solid #FED7AA", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 14 }}>
              <i className={`bi ${s.icon}`} style={{ fontSize: 18, color: "#F97316" }} />
            </div>
            <h3 style={S.cardLabel}>{s.label}</h3>
            <h2 style={{ ...S.cardValue, color: s.color, fontSize: 36 }}>{s.value}</h2>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: 10, marginBottom: 20 }}>
        {["All","Available","Occupied","Maintenance"].map(f => (
          <button key={f} onClick={() => setFilter(f)} style={{ padding: "10px 18px", borderRadius: 12, border: "1px solid", borderColor: filter === f ? "#F97316" : "#FED7AA", background: filter === f ? "#F97316" : "#fff", color: filter === f ? "#fff" : "#6B7280", fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: "Inter, sans-serif" }}>
            {f}
          </button>
        ))}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 16 }}>
        {filtered.map(room => {
          const sc = statusColor[room.status];
          return (
            <div key={room.name} style={{ background: "#fff", borderRadius: 22, padding: 22, border: "1px solid #FED7AA", boxShadow: "0 4px 16px rgba(249,115,22,0.06)" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 14 }}>
                <div style={{ width: 48, height: 48, background: "#FFF7ED", borderRadius: 14, display: "flex", alignItems: "center", justifyContent: "center", border: "1px solid #FED7AA" }}>
                  <i className={`bi ${room.icon}`} style={{ fontSize: 22, color: "#F97316" }} />
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 6, background: sc.bg, color: sc.color, padding: "5px 10px", borderRadius: 999, fontSize: 11, fontWeight: 700 }}>
                  <div style={{ width: 6, height: 6, borderRadius: "50%", background: sc.dot }} />
                  {room.status}
                </div>
              </div>
              <div style={{ fontWeight: 800, fontSize: 15, color: "#111827", marginBottom: 2 }}>{room.name}</div>
              <div style={{ fontSize: 12, color: "#9CA3AF", marginBottom: 10 }}>{room.type}</div>
              <div style={{ display: "flex", gap: 12, marginBottom: 14 }}>
                <div style={{ fontSize: 12, color: "#6B7280", display: "flex", alignItems: "center", gap: 4 }}>
                  <i className="bi bi-people" style={{ fontSize: 13 }} />
                  Up to {room.capacity}
                </div>
                <div style={{ fontSize: 12, color: "#F97316", fontWeight: 700 }}>{room.price}</div>
              </div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 16 }}>
                {room.amenities.map(a => (
                  <span key={a} style={{ fontSize: 11, background: "#FFF7ED", color: "#EA580C", padding: "3px 8px", borderRadius: 6, border: "1px solid #FED7AA", fontWeight: 600 }}>{a}</span>
                ))}
              </div>
              <button style={{ width: "100%", padding: "10px", borderRadius: 12, border: room.status === "Maintenance" ? `1px solid ${sc.bg}` : "1px solid #FED7AA", background: room.status === "Maintenance" ? sc.bg : "#FFF7ED", color: room.status === "Maintenance" ? sc.color : "#F97316", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: "Inter, sans-serif" }}>
                {room.status === "Maintenance" ? "Report Issue" : "View Details"}
              </button>
            </div>
          );
        })}
      </div>
    </>
  );
}

function MessagesPanel() {
  const [selectedConv, setSelectedConv] = useState(0);
  const [conversations, setConversations] = useState(CONVERSATIONS);
  const [input, setInput] = useState("");

  const conv = conversations[selectedConv];

  const sendMessage = () => {
    if (!input.trim()) return;
    const now = new Date();
    const time = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    setConversations(prev => prev.map((c, i) =>
      i === selectedConv
        ? { ...c, messages: [...c.messages, { from: "me", text: input, time }], last: input, unread: 0 }
        : c
    ));
    setInput("");
  };

  const handleSelect = (i) => {
    setSelectedConv(i);
    setConversations(prev => prev.map((c, idx) => idx === i ? { ...c, unread: 0 } : c));
  };

  return (
    <div style={{ display: "grid", gridTemplateColumns: "300px 1fr", gap: 16, height: "calc(100vh - 180px)" }}>
      <div style={{ background: "#fff", borderRadius: 22, border: "1px solid #FED7AA", overflow: "hidden", display: "flex", flexDirection: "column" }}>
        <div style={{ padding: "18px 18px 12px", borderBottom: "1px solid #FED7AA" }}>
          <h2 style={{ margin: "0 0 12px", fontSize: 16, fontWeight: 800, color: "#111827" }}>Messages</h2>
          <div style={{ position: "relative" }}>
            <i className="bi bi-search" style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", color: "#9CA3AF", fontSize: 14 }} />
            <input placeholder="Search messages..." style={{ ...S.searchInput, paddingLeft: 36, height: 38, fontSize: 13 }} />
          </div>
        </div>
        <div style={{ flex: 1, overflowY: "auto" }}>
          {conversations.map((c, i) => (
            <div key={c.id} onClick={() => handleSelect(i)} style={{ display: "flex", alignItems: "center", gap: 12, padding: "14px 18px", cursor: "pointer", background: selectedConv === i ? "#FFF7ED" : "transparent", borderBottom: "1px solid #F9FAFB", transition: "background 0.15s" }}>
              <div style={{ position: "relative", flexShrink: 0 }}>
                <Avatar init={c.init} size={40} bg={c.role === "Admin" ? "#1F2937" : "#F97316"} />
                {c.unread > 0 && (
                  <div style={{ position: "absolute", top: -3, right: -3, width: 16, height: 16, borderRadius: "50%", background: "#F97316", color: "#fff", fontSize: 9, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center" }}>{c.unread}</div>
                )}
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 3 }}>
                  <span style={{ fontWeight: 700, fontSize: 14, color: "#111827" }}>{c.name}</span>
                  <span style={{ fontSize: 11, color: "#9CA3AF" }}>{c.time}</span>
                </div>
                <div style={{ fontSize: 12, color: c.unread > 0 ? "#374151" : "#9CA3AF", fontWeight: c.unread > 0 ? 600 : 400, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.last}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div style={{ background: "#fff", borderRadius: 22, border: "1px solid #FED7AA", display: "flex", flexDirection: "column", overflow: "hidden" }}>
        <div style={{ padding: "16px 22px", borderBottom: "1px solid #FED7AA", display: "flex", alignItems: "center", gap: 12 }}>
          <Avatar init={conv.init} size={40} bg={conv.role === "Admin" ? "#1F2937" : "#F97316"} />
          <div>
            <div style={{ fontWeight: 700, fontSize: 15, color: "#111827" }}>{conv.name}</div>
            <div style={{ fontSize: 12, color: "#9CA3AF" }}>{conv.role} • Active now</div>
          </div>
        </div>
        <div style={{ flex: 1, overflowY: "auto", padding: "20px 22px", display: "flex", flexDirection: "column", gap: 14 }}>
          {conv.messages.map((m, i) => (
            <div key={i} style={{ display: "flex", flexDirection: m.from === "me" ? "row-reverse" : "row", alignItems: "flex-end", gap: 8 }}>
              {m.from !== "me" && <Avatar init={conv.init} size={30} bg={conv.role === "Admin" ? "#1F2937" : "#F97316"} />}
              <div style={{ maxWidth: "65%" }}>
                <div style={{ background: m.from === "me" ? "#F97316" : "#F9FAFB", color: m.from === "me" ? "#fff" : "#111827", padding: "10px 14px", borderRadius: m.from === "me" ? "18px 18px 4px 18px" : "18px 18px 18px 4px", fontSize: 14, lineHeight: 1.5, boxShadow: m.from === "me" ? "0 4px 12px rgba(249,115,22,0.25)" : "none" }}>
                  {m.text}
                </div>
                <div style={{ fontSize: 11, color: "#9CA3AF", marginTop: 4, textAlign: m.from === "me" ? "right" : "left" }}>{m.time}</div>
              </div>
            </div>
          ))}
        </div>
        <div style={{ padding: "14px 22px", borderTop: "1px solid #FED7AA", display: "flex", gap: 10, alignItems: "center" }}>
          <input
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === "Enter" && sendMessage()}
            placeholder="Type a message..."
            style={{ ...S.searchInput, flex: 1, height: 44 }}
          />
          <button onClick={sendMessage} style={{ width: 44, height: 44, borderRadius: 14, background: "#F97316", border: "none", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", boxShadow: "0 4px 12px rgba(249,115,22,0.35)", flexShrink: 0 }}>
            <i className="bi bi-send-fill" style={{ fontSize: 17, color: "#fff" }} />
          </button>
        </div>
      </div>
    </div>
  );
}

