const PAGE_META = {
  dashboard: { title: "Dashboard Overview",  sub: "Welcome back! Here's today's resort summary." },
  bookings:  { title: "Bookings",            sub: "Manage all guest reservations."               },
  guests:    { title: "Guests",              sub: "View and manage guest profiles."              },
  rooms:     { title: "Rooms & Spaces",      sub: "Monitor room availability and status."       },
  messages:  { title: "Messages",            sub: "Communicate with guests and admin."           },
};

export default function StaffDashboard() {
  const navigate = useNavigate();
  const [active, setActive] = useState("dashboard");
  const [bookings, setBookings] = useState([]);
  const [bookingError, setBookingError] = useState("");

  useEffect(() => {
    let isCurrent = true;
    apiRequest("/reservations")
      .then(({ reservations }) => {
        if (isCurrent) setBookings(reservations.map(toDashboardReservation));
      })
      .catch((error) => {
        if (isCurrent) setBookingError(error.message);
      });
    return () => { isCurrent = false; };
  }, []);

  async function updateBookingStatus(booking, status) {
    try {
      await apiRequest(`/reservations/${booking.reservationId}/status`, {
        method: "PATCH",
        body: JSON.stringify({ status }),
      });
      setBookings((current) => current.map((item) => item.reservationId === booking.reservationId ? { ...item, status } : item));
      setBookingError("");
    } catch (error) {
      setBookingError(error.message);
    }
  }

  const user = JSON.parse(localStorage.getItem("user") || "{}");
  const initials = user.name ? user.name.split(" ").map(n => n[0]).join("").toUpperCase() : "S";

  const panels = {
    dashboard: <DashboardPanel bookings={bookings} />,
    bookings:  <BookingsPanel bookings={bookings} onStatusChange={updateBookingStatus} />,
    guests:    <GuestsPanel />,
    rooms:     <RoomsPanel />,
    messages:  <MessagesPanel />,
  };

  const handleLogout = () => {
    clearSession();
    navigate("/login");
  };

  const meta = PAGE_META[active];

  return (
    <div style={S.shell}>
      <aside style={S.sidebar}>
        <div style={S.logoBox}>
          <div>
            <h2 style={S.logoTitle}>Villa Tjeozabel</h2>
            <p style={S.logoSub}>STAFF DASHBOARD</p>
          </div>
        </div>

        <nav style={S.nav}>
          {navItems.map(item => (
            <button
              key={item.key}
              onClick={() => setActive(item.key)}
              style={{ ...S.navItem, ...(active === item.key ? S.activeNav : {}) }}
            >
              <i
                className={`bi ${item.icon}`}
                style={{ fontSize: 18, color: active === item.key ? "#fff" : "#EA580C", flexShrink: 0 }}
              />
              <span>{item.label}</span>
            </button>
          ))}
        </nav>

        <button style={S.logoutBtn} onClick={handleLogout}>
          <i className="bi bi-box-arrow-left" style={{ fontSize: 18, color: "#EA580C" }} />
          Logout
        </button>
      </aside>

      <main style={S.main}>
        <div style={S.topbar}>
          <div>
            <h1 style={S.title}>{meta.title}</h1>
            <p style={S.subtitle}>{meta.sub}</p>
          </div>
          <div style={S.topActions}>
            <div style={S.notification}>
              <i className="bi bi-bell" style={{ fontSize: 20, color: "#374151" }} />
              <span style={S.notifBadge}>3</span>
            </div>
            <div style={S.profile}>
              <div style={S.profileAvatar}>{initials}</div>
              <div>
                <p style={S.profileName}>{user.name || "Staff Member"}</p>
                <span style={S.profileRole}>Staff Member</span>
              </div>
            </div>
          </div>
        </div>

        {bookingError && <p role="alert" style={{ color: "#b42318" }}>{bookingError}</p>}
        {panels[active]}
      </main>
    </div>
  );
}
